import{_ as n,o as t,c as i,a3 as s}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"SVG-Line – Dessiner et animer des lignes de connexion","description":"","frontmatter":{"title":"SVG-Line – Dessiner et animer des lignes de connexion"},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/svg-line.md","filePath":"fr/projects/grafik-visual-studio/svg-line.md","lastUpdated":1793128957000}'),r={name:"fr/projects/grafik-visual-studio/svg-line.md"};function o(a,e,l,u,d,c){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="svg-line" tabindex="-1">SVG-Line <a class="header-anchor" href="#svg-line" aria-label="Permalink to &quot;SVG-Line {#svg-line}&quot;">​</a></h1><h2 id="anderungen-bis-studio-0-1-285" tabindex="-1">Modifications jusqu&#39;à la version Studio 0.1.285 <a class="header-anchor" href="#anderungen-bis-studio-0-1-285" aria-label="Permalink to &quot;Modifications jusqu&#39;à la version Studio 0.1.285 {#anderungen-bis-studio-0-1-285}&quot;">​</a></h2><ul><li>La <strong>position de départ verticale</strong>, située sous la rubrique <strong>Ligne</strong>, s&#39;applique aussi bien aux <em>SVG-Line</em> qu&#39;aux connexions de valeurs. Si l&#39;option n&#39;est pas cochée, une ligne libre débute horizontalement. Dans le cas d&#39;un tracé automatiquement orthogonal, une ligne verticale monte ou descend d&#39;abord, puis bifurque vers la droite ou la gauche à la hauteur de la cible. Ce comportement s&#39;applique également aux lignes ancrées ; les points intermédiaires définis manuellement restent prioritaires.</li><li>Le déplacement des points ne s&#39;amorce qu&#39;après un mouvement de souris d&#39;au moins <strong>6 pixels</strong>. Les poignées individuelles ne déclenchent pas de déplacement groupé et ne sautent pas vers la position de la souris. L&#39;autre point de connexion reste fixé. <strong>Ctrl + Glisser</strong> détache spécifiquement une extrémité ancrée ; <strong>Alt + Glisser sur la ligne</strong> déplace une ligne ancrée dans son intégralité et détache ses deux extrémités.</li><li>Un <strong>index Z (Z-index) de -100 ou moins</strong> masque une ligne SVG uniquement lors de l&#39;exécution (runtime). Elle reste modifiable dans l&#39;éditeur et continue de transmettre des valeurs (par exemple, d&#39;un composant « Number » vers « Math »), indépendamment de son ordre d&#39;affichage dans l&#39;éditeur.</li><li>À partir de la version <strong>0.1.282</strong>, une sortie active de type « Gauge/Potentiomètre » ou « Linear » fournit directement la vitesse et la direction de la ligne SVG connectée, sans nécessiter d&#39;entité numérique intermédiaire. Utilisez le paramètre <strong>« Poti / SVG LineBox-Teiler » (diviseur)</strong> : une valeur de 10 avec un diviseur de 10 donne 1 cycle/s ; une valeur de 20 avec un diviseur de 10 donne 2 cycles/s. Une valeur de zéro arrête l&#39;animation, tandis que des valeurs négatives l&#39;inversent. Avec un diviseur de 1, toute valeur égale ou supérieure à 20 atteint la vitesse maximale de 20 cycles/s. Pour obtenir une vitesse dépendante de la valeur, désactivez l&#39;ajustement automatique du diviseur ; lorsqu&#39;il est activé, ce mécanisme maintient volontairement la vitesse cible constante. Les connexions de valeurs en elles-mêmes ne comportent pas d&#39;animation.</li></ul><p>Vous trouverez la structure ainsi qu&#39;une démonstration animée en cours d&#39;exécution dans la <a href="/fr/projects/grafik-visual-studio/bildergalerie">Galerie</a>.</p><p>À partir de la version Studio 0.1.136, une fonction d&#39;<strong>ajustement automatique du diviseur</strong> est disponible pour les entités numériques et les sorties « LineBox ». Elle permet de maintenir une vitesse d&#39;animation constante, même lorsque les valeurs (puissances) varient. La configuration et le calcul sont expliqués ci-dessous, dans la section <strong>Ajustement automatique du diviseur : comment et pourquoi</strong>.</p><p>Vous trouverez <strong>SVG-Line</strong> sous la rubrique <strong>HA Grafik – Spezial</strong>. Ce widget permet de relier visuellement d&#39;autres widgets, de faire passer des lignes par des angles et d&#39;animer un flux de données. Une ligne peut commencer et se terminer au niveau des points d&#39;ancrage d&#39;un widget, sur un point de regroupement (« Sammelpunkt ») explicitement activé d&#39;une autre SVG-Line, ou à des coordonnées libres. Il ne s&#39;agit pas, en soi, d&#39;une entité Home Assistant ; une entité optionnelle permet de piloter son animation.</p><h2 id="verbindung-und-andockpunkte" tabindex="-1">Connexion et points d&#39;ancrage <a class="header-anchor" href="#verbindung-und-andockpunkte" aria-label="Permalink to &quot;Connexion et points d&#39;ancrage {#verbindung-und-andockpunkte}&quot;">​</a></h2><ol><li>Ajoutez un élément SVG-Line. Sélectionnez-le dans l&#39;éditeur ; le début et la fin apparaissent sous forme de cercles déplaçables.</li><li>Sur le widget cible, activez les <strong>points d&#39;ancrage</strong> et sélectionnez les positions souhaitées. Sur les nouveaux widgets, ces douze points sont désactivés par défaut : à gauche et à droite (en haut, au milieu et en bas) ; en haut et en bas (à 1/4, au milieu et aux 3/4). L&#39;option <strong>Tous les points</strong> permet de les activer ou désactiver simultanément. Plusieurs lignes peuvent occuper le même point.</li><li>Faites glisser une extrémité de la ligne vers un point d&#39;ancrage actif. Vous pouvez également définir le widget et le point d&#39;ancrage correspondants dans les sections <strong>Début</strong> et <strong>Fin</strong>. L&#39;option <strong>Ou point de regroupement actif</strong> permet de sélectionner un point de regroupement appartenant à une autre SVG-Line, tandis que <strong>X/Y libre</strong> permet de positionner une extrémité sans contrainte de rattachement.</li></ol><table tabindex="0"><thead><tr><th>Manipulation</th><th>Effet</th></tr></thead><tbody><tr><td>Déplacer une extrémité libre</td><td>Modifie le début ou la fin de la ligne. Les touches fléchées permettent de déplacer un point sélectionné de 1 pixel ; l&#39;utilisation de <code>Umschalt</code> permet un déplacement de 10 pixels.</td></tr><tr><td>Déplacer une extrémité ancrée avec <code>Strg</code></td><td>Rompt la connexion et déplace le point. L&#39;utilisation de <code>Strg</code> combinée à une touche fléchée permet également cette opération.</td></tr><tr><td>Déplacer un point intermédiaire</td><td>Modifie le tracé d&#39;une ligne composée de plusieurs segments.</td></tr><tr><td>Déplacer la ligne entière</td><td>Déplacement direct pour une ligne libre ; utilisation de <code>Alt</code> pour une ligne ancrée. Déplace la ligne dans son intégralité, en supprimant les ancrages existants au niveau du point de départ ou d&#39;arrivée.</td></tr><tr><td>Cliquer sur la ligne (sans la faire glisser)</td><td>Ouvre un menu permettant de choisir entre <strong>Point intermédiaire</strong>, <strong>Point de regroupement</strong> ou <strong>Point de couplage de valeur</strong> ; le point est inséré après validation par <strong>OK</strong>.</td></tr></tbody></table><h2 id="pfad-und-sammelpunkte" tabindex="-1">Tracé et points de regroupement <a class="header-anchor" href="#pfad-und-sammelpunkte" aria-label="Permalink to &quot;Tracé et points de regroupement {#pfad-und-sammelpunkte}&quot;">​</a></h2><h3 id="wert-koppelpunkt-fur-eine-freie-anzeige" tabindex="-1">Point de couplage de valeur pour un affichage libre <a class="header-anchor" href="#wert-koppelpunkt-fur-eine-freie-anzeige" aria-label="Permalink to &quot;Point de couplage de valeur pour un affichage libre {#wert-koppelpunkt-fur-eine-freie-anzeige}&quot;">​</a></h3><p>À partir de la version <strong>0.1.275</strong>, un troisième type de point est disponible : le <strong>point de couplage de valeur</strong>. Il restitue la valeur associée à la ligne SVG, telle que la valeur numérique de son entité d&#39;animation ou la valeur provenant de sa source connectée. Dans l&#39;éditeur, il est représenté par un octogone ; sa couleur se règle via <strong>Paramètres → Point de couplage de valeur</strong>. Il s&#39;agit exclusivement d&#39;un point de sortie ; il ne peut donc pas servir de destination pour une ligne.</p><p>À partir de la version <strong>0.1.281</strong>, le point de couplage de valeur ne peut être déplacé que <strong>le long du tracé visible de la ligne</strong>. Lors du déplacement, il reste calé sur le point le plus proche de la ligne, y compris sur les courbes et les angles arrondis. Il ne modifie ni le tracé de la ligne ni le type de chemin sélectionné ; seuls les points intermédiaires et les points de regroupement définissent le chemin. Une fois déplacé, la connexion d&#39;affichage sortante s&#39;ajuste automatiquement à la nouvelle position. Les points existants situés à côté de la ligne, ainsi que les positions saisies manuellement, sont replacés sur le chemin.</p><ol><li>Sélectionnez la ligne SVG, cliquez à nouveau à l&#39;endroit souhaité et insérez un <strong>point de couplage de valeur</strong>.</li><li>Placez un widget <strong>Number</strong> (Nombre) librement à côté, au-dessus ou en dessous de la ligne. Dans la section <strong>Flux de données</strong>, activez son <strong>point d&#39;entrée</strong> et définissez son côté.</li><li>Créez une connexion. Sous <strong>Début → Point de regroupement ou de couplage de valeur</strong>, sélectionnez le nouveau point (ou faites glisser l&#39;extrémité de la connexion sur celui-ci). Reliez ensuite la destination à l&#39;entrée du widget Number.</li></ol><p>Le point et la connexion sortante sont automatiquement invisibles lors de l&#39;exécution (runtime), mais le transfert de valeur reste actif. La ligne SVG d&#39;origine demeure visible. Le widget <strong>String</strong> (Chaîne de caractères) peut être utilisé de la même manière pour afficher une valeur textuelle issue du flux de données. Les <strong>points de ligne</strong> permettent de modifier ultérieurement le nom, la position et le type de point. Les valeurs inconnues ne sont pas remplacées par une valeur nulle arbitraire.</p><p>Sous <strong>Tracé et points de jonction</strong>, on trouve quatre <strong>types de tracé</strong> : <strong>Ligne droite</strong>, <strong>Angle droit automatique</strong>, <strong>Courbe</strong> et <strong>Tracé manuel en zigzag/à points multiples</strong>. Le <strong>rayon d&#39;angle</strong> permet d&#39;arrondir les angles du tracé. La section <strong>Points intermédiaires et points de jonction</strong> permet de nommer, placer et modifier des points. L&#39;ajout d&#39;un point intermédiaire ou d&#39;un point de jonction par un simple clic fait passer la ligne en mode manuel à points multiples.</p><p>Un <strong>point intermédiaire</strong> se contente de créer un coude dans le tracé. Un <strong>point de jonction</strong>, lorsqu&#39;il est activé, sert de point de connexion potentiel pour d&#39;autres lignes SVG. Pour effectuer la connexion, faites glisser l&#39;extrémité libre de la ligne vers le point de jonction visible, ou sélectionnez ce dernier dans les propriétés. Plusieurs lignes peuvent utiliser le même point de jonction. Un simple croisement ou contact ne crée pas de liaison entre les lignes. Un point de jonction désactivé n&#39;accepte aucune nouvelle connexion.</p><h2 id="linie-und-pfeilspitzen" tabindex="-1">Ligne et pointes de flèche <a class="header-anchor" href="#linie-und-pfeilspitzen" aria-label="Permalink to &quot;Ligne et pointes de flèche {#linie-und-pfeilspitzen}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Groupe</th><th>Options de configuration</th></tr></thead><tbody><tr><td><strong>Ligne</strong></td><td><strong>Couleur de base</strong>, <strong>couleur d&#39;animation</strong>, <strong>épaisseur</strong> (1–40 px), <strong>opacité</strong>, <strong>type de ligne</strong> (continue, en pointillés, en tirets), <strong>longueur des tirets</strong>, <strong>espacement</strong> entre les tirets/points et <strong>extrémités de ligne</strong> (arrondies, plates, carrées).</td></tr><tr><td><strong>Pointes de flèche</strong></td><td><strong>Au début</strong> et <strong>à la fin</strong> (indépendantes) : aucune, flèche pleine, flèche ouverte ou cercle. La <strong>taille</strong> et la <strong>couleur</strong> s&#39;appliquent aux marqueurs. Si le sens du flux est inversé, les marqueurs affichés changent de côté.</td></tr></tbody></table><h2 id="animation-und-richtungsquelle" tabindex="-1">Animation et source de direction <a class="header-anchor" href="#animation-und-richtungsquelle" aria-label="Permalink to &quot;Animation et source de direction {#animation-und-richtungsquelle}&quot;">​</a></h2><p>Activez l&#39;option <strong>Activer l&#39;animation</strong> et choisissez un <strong>type d&#39;animation</strong> : flux bicolore, tirets en mouvement, pulsation ou point lumineux. Sous <strong>Source de direction</strong>, une seule variante est active à la fois :</p><table tabindex="0"><thead><tr><th>Source</th><th>Direction et vitesse</th></tr></thead><tbody><tr><td><strong>Manuel</strong></td><td><strong>Direction</strong> : du début vers la fin ou de la fin vers le début ; <strong>durée</strong> : de 0,2 à 20 secondes par cycle. En cas de connexion à un point de convergence, le flux manuel s&#39;oriente vers ce point.</td></tr><tr><td><strong>Entité numérique</strong></td><td>Les valeurs positives génèrent un mouvement du début vers la fin, les valeurs négatives dans le sens inverse ; la valeur <code>0</code> arrête le flux. La valeur absolue divisée par le <strong>diviseur</strong> (par défaut : <code>1</code>) donne le nombre de cycles par seconde (limite : 0,05 à 20). Exemple : <code>1000 W ÷ 100 = 10</code> cycles/s.</td></tr><tr><td><strong>Entité booléenne</strong></td><td><code>on</code>/<code>true</code>/<code>1</code> s&#39;exécute vers l&#39;avant, <code>off</code>/<code>false</code>/<code>0</code> vers l&#39;arrière. L&#39;option <strong>Inverser la direction (booléen)</strong> échange cette affectation. La <strong>durée</strong> définie détermine la cadence.</td></tr></tbody></table><p>Des états d&#39;entité manquants ou invalides interrompent l&#39;animation. L&#39;entité sélectionnée est mise à jour dans l&#39;éditeur et lors de l&#39;exécution (runtime). La <strong>SVG LineBox</strong> peut transmettre le signe et la valeur absolue de sa valeur calculée à la ligne, via un point d&#39;ancrage configuré comme sortie. Cette transmission est prioritaire sur la source de direction choisie. La ligne de sortie nécessite toujours l&#39;activation de l&#39;option <strong>Activer l&#39;animation</strong> ; en présence de <code>0</code> ou en l&#39;absence d&#39;entrée valide, elle reste immobile. Le paramètre <strong>Diviseur SVG LineBox (lors de la transmission)</strong> détermine alors sa cadence, tandis que ses propres couleurs et son type de ligne sont conservés. <a href="/fr/projects/grafik-visual-studio/svg-linebox">Explication détaillée de la SVG LineBox</a>.</p><h2 id="automatische-teileranpassung-wie-und-warum" tabindex="-1">Ajustement automatique du diviseur : comment et pourquoi <a class="header-anchor" href="#automatische-teileranpassung-wie-und-warum" aria-label="Permalink to &quot;Ajustement automatique du diviseur : comment et pourquoi {#automatische-teileranpassung-wie-und-warum}&quot;">​</a></h2><p>Avec un diviseur fixe, la vitesse augmente proportionnellement à la valeur d&#39;entrée. Si l&#39;on utilise le diviseur <code>100</code>, par exemple, <code>10 W</code> ne produit que <code>0,1</code> cycles/s, alors que <code>1500 W</code> en produit déjà <code>15</code> cycles/s. Un diviseur plus élevé permet de modérer les puissances élevées (comme celles d&#39;un système de chauffage ou d&#39;une plaque de cuisson), mais rend les petites valeurs très lentes. À l&#39;inverse, un diviseur plus faible accélère les petites valeurs, mais peut rendre les grandes valeurs difficiles à distinguer lors de l&#39;animation.</p><p>Le mode automatique ajuste donc le diviseur en fonction de la <strong>vitesse cible</strong> choisie, à chaque modification de la valeur. Il n&#39;utilise pas de paliers de puissance fixes et fonctionne également au-delà de 15.000. La relation est la suivante :</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Automatischer Teiler = Betrag des Eingangswerts / Zielgeschwindigkeit</span></span>
<span class="line"><span>Animationsgeschwindigkeit = Betrag des Eingangswerts / automatischer Teiler</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Pour <strong>1 cycle/s</strong>, on obtient les valeurs suivantes :</p><table tabindex="0"><thead><tr><th>Valeur d&#39;entrée</th><th>Diviseur automatique</th><th>Vitesse</th></tr></thead><tbody><tr><td>10</td><td>10</td><td>1 cycle/s</td></tr><tr><td>100</td><td>100</td><td>1 cycle/s</td></tr><tr><td>1500</td><td>1500</td><td>1 cycle/s</td></tr><tr><td>15.000</td><td>15.000</td><td>1 cycle/s</td></tr></tbody></table><p>Ainsi, le flux reste tout aussi bien perceptible, qu&#39;il s&#39;agisse de faibles ou de fortes puissances. Lorsque le mode automatique est activé, la vitesse affichée correspond à la vitesse cible choisie ; il n&#39;est donc plus possible de déduire le niveau de puissance à partir de cette seule information. Le signe continue de déterminer la direction. La valeur <code>0</code>, l&#39;absence de valeur ou des états invalides entraînent l&#39;arrêt de l&#39;animation.</p><h3 id="einrichten" tabindex="-1">Configuration <a class="header-anchor" href="#einrichten" aria-label="Permalink to &quot;Configuration {#einrichten}&quot;">​</a></h3><ol><li>Sélectionnez la ligne SVG et, sous la rubrique <strong>Animation</strong>, cochez <strong>Activer l&#39;animation</strong>.</li><li>Si vous utilisez une source numérique (Home Assistant), sélectionnez <strong>Source de direction → Entité numérique</strong>, saisissez l&#39;entité concernée et activez l&#39;option <strong>Ajuster automatiquement le diviseur (entité numérique)</strong>.</li><li>Si vous utilisez une sortie connectée provenant de <strong>SVG LineBox</strong> ou de <a href="/fr/projects/grafik-visual-studio/svg-linebox-math"><strong>SVG LineBox Math</strong></a>, activez plutôt l&#39;option <strong>Ajuster automatiquement le diviseur (SVG LineBox)</strong>. Ce mode de transmission de valeur est prioritaire sur la source de direction choisie. 4. Réglez la <strong>vitesse cible</strong> correspondante. La valeur par défaut est de <strong>1 cycle/s</strong> ; les valeurs autorisées sont comprises entre <strong>0,05 et 5 cycles/s</strong>. Avec <code>0,5</code>, un cycle dure deux secondes ; avec <code>2</code>, il dure une demi-seconde. Commencez avec <code>1</code> et ajustez la valeur en fonction du type de ligne et de l&#39;espacement des traits.</li></ol><p>Les deux modes automatiques sont indépendants et désactivés par défaut. Le <strong>diviseur</strong> manuel correspondant est mémorisé ; il est réutilisé lorsque le mode automatique est désactivé. Les modes <strong>Manuel</strong> et <strong>Entité booléenne</strong> continuent d&#39;utiliser leur durée définie. Une animation de ligne principale héritée reste appliquée aux lignes secondaires normales ; une valeur LineBox transmise activement détermine elle-même le rythme de la ligne de sortie concernée.</p><p>Le nombre de cycles par seconde correspond aux répétitions de l&#39;animation, et non à une vitesse en pixels. Le type de ligne, le type d&#39;animation et l&#39;espacement des traits influencent le résultat visuel. Le mode automatique assure un rythme stable ; la vitesse cible appropriée peut donc être réglée individuellement pour chaque ligne.</p><h2 id="hauptlinie-kreuzungen-und-ebenen" tabindex="-1">Ligne principale, intersections et niveaux <a class="header-anchor" href="#hauptlinie-kreuzungen-und-ebenen" aria-label="Permalink to &quot;Ligne principale, intersections et niveaux {#hauptlinie-kreuzungen-und-ebenen}&quot;">​</a></h2><p>La fonction <strong>Ligne principale / Groupe de flux</strong> permet d&#39;associer une ligne à une autre. L&#39;option <strong>Reprendre le rythme d&#39;animation de la ligne principale (conserver ses propres couleurs)</strong> applique le rythme et le type d&#39;animation de la ligne principale, tout en permettant à la ligne secondaire de conserver sa propre couleur pendant l&#39;animation du flux. La <strong>Synchronisation</strong> propose les modes <strong>Même rythme</strong> et <strong>Arrivée synchronisée au point de convergence</strong>. En cas de connexion directe à un point de convergence situé sur une ligne principale non animée, la ligne secondaire s&#39;arrête également et affiche sa couleur de base, pointes de flèches incluses. Une fois la connexion supprimée, les paramètres propres à la ligne sont rétablis.</p><p>Les paramètres <strong>Croisement et z-index</strong> permettent de gérer l&#39;affichage des intersections via les options <strong>Superposition</strong>, <strong>Lacune</strong> ou <strong>Pont / Arche</strong>, ainsi que de définir l&#39;empilement (z-index) via les modes <strong>Automatique</strong>, <strong>Au-dessus</strong>, <strong>En dessous</strong> ou <strong>Manuel</strong>. Un élément doté d&#39;un z-index plus élevé s&#39;affiche visuellement devant un élément ayant un z-index plus faible. L&#39;option <strong>Laisser passer les clics</strong> influe sur l&#39;interactivité lors de l&#39;exécution (runtime). La gestion des croisements et le z-index ne créent pas de connexion physique entre les lignes ; pour cela, il est nécessaire d&#39;utiliser un point de convergence ou le composant <a href="/fr/projects/grafik-visual-studio/svg-linebox">SVG LineBox</a>.</p><p>La fonctionnalité SVG-Line est encore au stade expérimental ; le rendu des croisements et des animations synchronisées peut varier en fonction du tracé et du navigateur utilisé.</p>`,38)])])}const m=n(r,[["render",o]]);export{g as __pageData,m as default};
